(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zp-sj-prepa-gyneco-j3-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zp-sj-prepa-gyneco-j3-sf3\",\n \"titre\": \"Préparation D.E (J) · J3 Gynéco-obstétrique SF3\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 42,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n   \"sha256\": \"9ee0174cae6a310ff499e14b7685289c3bf3a2155e497e3971a6b1d18f45aa2e\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J3 (SF3)\",\n     \"slug\": \"prepa-gyneco-j3-sf3\",\n     \"pages\": \"\",\n     \"count\": 42,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'une des indications de l'échographie au premier trimestre de la grossesse, est d'apprécier la morphologie fœtale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'échographie du 1er trimestre sert surtout à confirmer la grossesse, préciser son siège, son âge, le nombre d'embryons et leur vitalité. L'étude de la morphologie fœtale est l'objectif de l'échographie du 2e trimestre. Remarque : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025) p. 195 cite aussi un premier repérage de la morphologie (clarté nucale) à l'échographie de 11-14 SA ; l'examen morphologique proprement dit reste celui du 2e trimestre.\\n\\nSource : Cours de soins obstétricaux L2 SF, CPN recentrée (3 échographies) ; Cours de Gynéco-Obstétrique 1re année (INFAS), Diagnostic de la grossesse au début\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fièvre, chez une femme enceinte, se définit par une température rectale à partir de 38°C au repos et dans un environnement normal\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La fièvre est une température centrale (rectale) égale ou supérieure à 38 °C, mesurée au repos. Chez la femme enceinte, toute fièvre doit être considérée comme un paludisme jusqu'à preuve du contraire. Remarque : L'algorithme « infection au cours de la grossesse » du SONU L3 SF (p. 7) utilise le seuil de 37,8 °C.\\n\\nSource : SONU L3 SF, Fièvre pendant la grossesse p. 86\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle de ménopause précoce lorsque la ménopause survient avant l'âge de 45 ans\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La ménopause précoce est une ménopause survenant avant 40 ans (et non 45 ans).\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Infertilité – causes féminines p. 187\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"le fer ne doit pas être prescrit chez les gestantes qui ont une drépanocytose majeure\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la drépanocytose majeure, l'anémie est hémolytique et non ferriprive : les réserves en fer sont souvent élevées (transfusions répétées), un apport de fer systématique expose à la surcharge. On donne surtout de l'acide folique. La gestante doit être suivie en centre spécialisé.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Hémoglobinopathies et grossesse p. 17 (partiellement hors cours pour la contre-indication du fer)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, le dépistage de l'allo-immunisation rhésus se fait par le test de Coombs indirect\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le test de Coombs indirect, fait chez la gestante Rhésus négatif, recherche dans son sang des anticorps anti-D ; il est répété à chaque CPN s'il est négatif.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Allo-immunisation Rhésus p. 20 ; SONU L3 SF, Incompatibilité p. 43\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"lors de l'administration de la Sulfadoxine Pyriméthamine chez la femme enceinte sous prophylaxie antianémique avec l'acide folique, il est recommandé dès la prise de la Sulfadoxine- Pyriméthamine de suspendre durant 14 jours le traitement antianémique par l'acide folique si la dose de l'acide folique atteint ou dépasse 5 mg/jour et le reprendre au 15ème jour\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'acide folique à 5 mg/jour ou plus diminue l'efficacité de la SP (antifolique). On suspend donc l'acide folique pendant 14 jours à partir de la prise de SP et on le reprend au 15e jour. Remarque : Le SONU L3 SF (Anémie p. 28) parle d'une semaine d'arrêt ; le cours de Gynéco-Obstétrique L3 donne bien 14 jours.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Paludisme et grossesse p. 8 et Anémie p. 15\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le plasmodium vivax est l'espèce de plasmodium qui tue\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"C'est Plasmodium falciparum qui est responsable du paludisme grave et mortel (fièvre tierce maligne). P. vivax donne une fièvre tierce bénigne.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Paludisme et grossesse p. 3\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il ya anémie sévère lorsque le taux d'hémoglobine est inférieur à 8 g/dl\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au cours de la grossesse, l'anémie est dite sévère quand le taux d'hémoglobine est inférieur à 8 g/100 ml. Remarque : Dans le paludisme grave (p. 4), l'« anémie grave » est définie par un taux d'hémoglobine inférieur à 7 g/dl.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Anémie et grossesse p. 9\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La nécrobiose aseptique est une complication fréquente du fibrome utérin au cours de la grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La nécrobiose aseptique est la complication la plus fréquente du myome pendant la grossesse ; non traitée, elle peut entraîner une menace d'accouchement prématuré.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Fibrome et grossesse p. 46-47 ; Gynéco L2 IDE (INFAS 2025), Myome utérin\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les gestantes séropositives au VIH sous cotrimoxazole ne doivent pas bénéficier d'une prophylaxie antipaludique par le traitement préventif intermittent associant sulfadoxine et pyriméthamine\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cotrimoxazole a déjà un effet antipaludique prouvé ; y ajouter la SP expose au surdosage en sulfamides et aux effets indésirables. On ne donne donc pas de TPI à la SP à ces gestantes. Remarque : Le SONU L3 SF (p. 90) propose une autre conduite (donner la SP et arrêter le cotrimoxazole une semaine) ; les autres cours vont dans le sens de la correction.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Paludisme et grossesse p. 7-8 ; Cours de soins obstétricaux L2 SF, Paludisme et grossesse\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les cas de paludisme grave doivent être pris en charge au sein d'une formation sanitaire SONU-C.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le paludisme grave ou compliqué de la gestante se traite en soins intensifs : la sage-femme doit la référer vers un centre SONU C (centre de référence).\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Paludisme et grossesse p. 5 ; SONU L3 SF p. 88\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la lymphangite du sein, l'allaitement doit être poursuivi\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la lymphangite, le lait reste propre (signe de Budin négatif) : on poursuit l'allaitement. Il est arrêté dans la galactophorite et l'abcès (lait purulent).\\n\\nSource : SONU L3 SF, Affections mammaires p. 104\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour avoir une allo immunisation dans le système rhésus, il faut que la mère soit de rhésus négatif et le fœtus de rhésus positif\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Conditions de l'incompatibilité : mère Rh négatif, père géniteur Rh positif et fœtus Rh positif. Si le fœtus est Rh négatif, il n'y a pas d'immunisation.\\n\\nSource : SONU L3 SF, Incompatibilité p. 42 ; Gynécologie-Obstétrique L3 SF (INFAS 2024-2025) p. 19-20\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les traumatismes au cours de la grossesse peuvent induire un accouchement prématuré\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un traumatisme abdominal peut provoquer un décollement placentaire, une rupture des membranes ou des contractions, donc une menace ou un accouchement prématuré.\\n\\nSource : Traumatismes et grossesse (Pr Guié, INFAS) ; MAP – menace d'accouchement prématuré\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de ménopause confirmée, le taux de FSH est très bas\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À la ménopause, les ovaires ne répondent plus : la FSH est très augmentée (et la LH augmentée), alors que l'œstradiol est bas.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025) p. 162\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La stérilité primaire est l'inaptitude à concevoir de nouveau après avoir conçu\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ceci est la définition de la stérilité secondaire. La stérilité primaire est l'incapacité à concevoir pour la première fois.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Infertilité p. 185\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La malodeur vaginale encore appelée la vaginose bactérienne est une complication des leucorrhées à Gardnerella vaginalis\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La vaginose bactérienne n'est pas une complication : c'est l'infection elle-même, due à la prolifération de Gardnerella vaginalis (et d'anaérobies) au détriment des bacilles de Döderlein ; la mauvaise odeur en est un signe.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Leucorrhées p. 178\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le test diagnostique du diabète gestationnel est le test de O'Sullivan\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le test de O'Sullivan est un test de dépistage. Le diagnostic se fait par l'hyperglycémie provoquée par voie orale (HGPO).\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Diabète et grossesse p. 45\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le paludisme apparait plus grave chez la primipare\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours dit que le paludisme est plus grave chez la primigeste (1re grossesse) et son nouveau-né, pas chez la primipare.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Paludisme et grossesse p. 3\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'âge moyen de la ménopause est 50 ans.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La vie génitale va de la puberté (12-13 ans) à la ménopause, qui survient en moyenne vers 50 ans.\\n\\nSource : Cours de Gynéco-Obstétrique 1re année (INFAS), Cycle menstruel normal p. 26\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la césarienne est ou sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il est recommandé de renoncer à une grossesse ultérieure à partir de 5 césariennes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elle peut se pratiquer par la voie vaginale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Selon les incisions sur l'utérus, la césarienne corporéale est la plus pratiquée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"En périphérie, toutes les indications de césarienne sont synonymes de transfert\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les dystocies mécaniques sont des causes fréquentes de césarienne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Elle peut se pratiquer par la voie vaginale ; D. En périphérie, toutes les indications de césarienne sont synonymes de transfert ; E. Les dystocies mécaniques sont des causes fréquentes de césarienne\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Le cours distingue la césarienne abdominale et la césarienne vaginale (B). En périphérie, sans bloc opératoire, toute indication de césarienne impose un transfert (D). Les dystocies mécaniques (bassin rétréci…) sont une indication fréquente (E). C est faux : c'est la césarienne segmentaire qui est la plus pratiquée. A : le seuil de 5 césariennes ne figure pas dans le cours.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Césarienne p. 143 ; SONU L3 SF, Césarienne p. 57\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les indications de la ventouse obstétricale sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La prématurité\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"la cardiopathie maternelle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"la souffrance fœtale aigue\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La disproportion céphalo-pelvienne\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"la procidence du cordon battant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. la cardiopathie maternelle ; C. la souffrance fœtale aigue ; E. la procidence du cordon battant\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"La ventouse sert à raccourcir l'expulsion quand les efforts expulsifs sont dangereux (cardiopathie) ou quand il faut extraire vite l'enfant (souffrance fœtale aiguë, procidence du cordon battant à dilatation complète, tête engagée). La prématurité est une contre-indication (fragilité du crâne) et la disproportion céphalo-pelvienne impose la césarienne.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Extractions instrumentales p. 85-87 ; SONU L3 SF, Cardiopathie p. 98\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les principales causes des Hauteurs utérines élevées sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Erreur de terme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Kyste ovarien et grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"grossesse gémellaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"oligoamnios\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Gros fœtus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Erreur de terme ; C. grossesse gémellaire ; E. Gros fœtus\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Une HU supérieure à la normale fait rechercher une grossesse multiple, un gros fœtus (macrosomie), un hydramnios, un fibrome, mais aussi une erreur sur le terme. L'oligoamnios donne au contraire une HU basse. Remarque : Dans le cours de soins obstétricaux, l'erreur de terme est citée parmi les causes d'HU basse ; une erreur de terme peut fausser l'HU dans les deux sens.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), CAT devant les anomalies de la hauteur utérine p. 52 ; Cours de soins obstétricaux L2 SF, Admission de la parturiente\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"l'association syphilis et grossesse peut se compliquer de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"la syphilis congénitale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"rupture prématurée des membranes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Oligoamnios chronique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"accouchement prématuré\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"avortement spontané\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. la syphilis congénitale ; D. accouchement prématuré ; E. avortement spontané\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Après le 4e mois, le tréponème traverse le placenta : avortement spontané (parfois à répétition), accouchement prématuré, mort fœtale, hydramnios et syphilis congénitale. On note un hydramnios et non un oligoamnios. Remarque : Dans le sujet, la 1re option n'a pas de lettre (c'est l'option A).\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Syphilis et grossesse p. 28-29\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans une structure sanitaire avec un bloc opératoire fonctionnel, La sage-femme doit pratiquer des gestes urgents avant la césarienne. Ce sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Mettre en place une sonde nasogastrique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faire réaliser une Numération et Formule Sanguine ou un taux de l'hémoglobine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faire coucher la parturiente ou la gestante sur le dos\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Prescrire le kit d'intervention chirurgicale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Informer le médecin de venir réaliser la césarienne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Faire réaliser une Numération et Formule Sanguine ou un taux de l'hémoglobine ; D. Prescrire le kit d'intervention chirurgicale\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Avant une césarienne en urgence, la sage-femme fait les prélèvements (groupe-Rhésus, TP, TCK, NFS/hémoglobine) et vérifie ou complète le kit de césarienne. On place une sonde urinaire (pas nasogastrique) et la femme est installée en décubitus latéral gauche, pas sur le dos.\\n\\nSource : SONU L3 SF, Césarienne p. 59 ; Gynécologie-Obstétrique L3 SF (INFAS 2024-2025) p. 140\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les examens complémentaires ci-dessous font partie du bilan de base du couple infertile :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le spermogramme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le Test post coïtal de Hühner\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le dosage plasmatique de l'œstradiol\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La coelioscopie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'hystérosalpingographie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Le spermogramme ; B. Le Test post coïtal de Hühner ; E. L'hystérosalpingographie\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Le bilan de première intention associe le spermogramme (homme), le test post-coïtal de Hühner (glaire et spermatozoïdes) et l'hystérosalpingographie (cavité utérine et perméabilité des trompes). Les dosages hormonaux ciblés et la cœlioscopie viennent en 2e intention.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Infertilité – examens complémentaires p. 189\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"le dépistage du diabète gestationnel se fait en cas de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"âge maternel supérieur à 40 ans\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"prise de poids supérieur à 1kg par mois au cours de la grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"antécédent de gros fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"antécédent de morts né\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"antécédent personnel de diabète insulino-résistant\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. prise de poids supérieur à 1kg par mois au cours de la grossesse ; C. antécédent de gros fœtus ; D. antécédent de morts né\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Les critères de O'Sullivan font dépister les gestantes avec antécédents obstétricaux pathologiques (gros fœtus, mort-né…) ou une grossesse actuelle anormale (prise de poids > 1 kg/mois, hydramnios, macrosomie, glycosurie…). Une femme déjà diabétique n'a pas besoin de dépistage : son diabète est connu.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Diabète et grossesse p. 45\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"la ou les conditions de réalisation de l'épreuve du travail est ou sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"milieu obstétrico-chirurgical comprenant un bloc opératoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bassin maternel rétréci\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Absence de souffrance fœtale chronique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Présentation céphalique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Fœtus à terme de poids normal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. milieu obstétrico-chirurgical comprenant un bloc opératoire ; E. Fœtus à terme de poids normal\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Les 6 conditions du cours : présentation du sommet, fœtus à terme de poids normal, absence de souffrance fœtale aiguë, bassin limite (et non rétréci : le bassin rétréci est une contre-indication), surveillance très étroite, maternité avec bloc opératoire fonctionnel. Remarque : C et D sont proches du cours mais pas exacts : le cours dit « souffrance fœtale aiguë » et « présentation du sommet » (pas toute présentation céphalique).\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), L'épreuve du travail p. 137\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la covid 19 au cours de la grossesse n'est pas ou ne sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Il faut séparer le couple mère-enfant lorsque le pronostic vital de la mère et de l'enfant sont bien engagés\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Il y a un risque de malformation fœtale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'allaitement est contre-indiqué\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Il y a un risque élevé de transmission verticale prénatal\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Elle peut se compliquer de prééclampsie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Il y a un risque de malformation fœtale ; C. L'allaitement est contre-indiqué ; D. Il y a un risque élevé de transmission verticale prénatal\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"La question demande les affirmations fausses. Le COVID-19 n'est pas tératogène, l'allaitement n'est pas contre-indiqué (avec mesures barrières) et la transmission verticale prénatale est rare. Sont exactes : la séparation mère-enfant quand le pronostic vital est engagé, et le risque de pré-éclampsie.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Infection au COVID-19 et grossesse p. 31-32\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les facteurs de risque des leucorrhées pathologiques sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'usage de vêtement trop serré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'excès de toilette intime\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La multiplication des partenaires sexuels\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'usage des tampons protecteurs\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'usage des sous corps en coton\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. L'usage de vêtement trop serré ; B. L'excès de toilette intime ; C. La multiplication des partenaires sexuels ; D. L'usage des tampons protecteurs\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le cours cite : vêtements trop serrés, toilettes et douches vaginales excessives, multiplicité des partenaires, tampons protecteurs, sous-vêtements en tissu synthétique (macération). Le coton, au contraire, est conseillé.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Leucorrhées p. 177\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hémorragie de la délivrance se manifeste par les signes suivants :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"une hémorragie d'abondance minime\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"l'utérus est mou mal rétracté\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une hémorragie ayant tendance à s'arrêter spontanément.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une hémorragie externe douloureuse\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le sang est rouge, liquide ou en caillots\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. l'utérus est mou mal rétracté ; E. Le sang est rouge, liquide ou en caillots\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"L'hémorragie de la délivrance est une perte de sang de plus de 500 ml, faite de sang rouge liquide ou en caillots, indolore, qui ne s'arrête pas d'elle-même, souvent avec un utérus mou, mal rétracté (atonie, absence de globe de sécurité).\\n\\nSource : Cours de soins obstétricaux L2 SF, CAT devant les hémorragies du post-partum ; SONU L3 SF p. 29-30\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les causes fréquentes des ictères tout au long de la grossesse sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"la pré-éclampsie sévère\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"les vomissements gravidiques incoercibles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"l'accès palustre grave\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"la cholestase intra hépatique gravidique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"les hémoglobinopathies majeures\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. l'accès palustre grave ; E. les hémoglobinopathies majeures\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"« Tout au long de la grossesse » : hépatites virales, accès palustre grave, hémoglobinopathies majeures. Les autres causes dépendent du trimestre : vomissements incoercibles au 1er trimestre, cholestase et pré-éclampsie sévère aux 2e et 3e trimestres.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Ictère au cours de la grossesse p. 30\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les marqueurs du virus de l'hépatite B à demander dans le cadre de la Prévention de la transmission mère-enfant du virus de l'hépatite B sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les anticorps HBs\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les antigènes HBc totaux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les antigènes HBs\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"les anticorps anti HBe\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"les anticorps anti HBc totaux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Les antigènes HBs ; E. les anticorps anti HBc totaux\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Pour la PTME de l'hépatite B, on demande dès le 1er trimestre l'antigène HBs et les anticorps anti-HBc totaux ; selon les résultats, on vaccine la mère ou on organise la prise en charge.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Hépatite B et grossesse p. 36-37\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les leucorrhées à candida Albicans :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elles sont traitées par le métronidazole sous forme d'ovules\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Elles sont blanches, peu abondantes, grumeleuses, caillebottées\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elles sont favorisées par la grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elles s'accompagnent de Prurit vulvo-vaginal très intense\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Elles sont favorisées par les Œstroprogestatifs fortement dosés en progestérone\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Elles sont blanches, peu abondantes, grumeleuses, caillebottées ; C. Elles sont favorisées par la grossesse ; D. Elles s'accompagnent de Prurit vulvo-vaginal très intense\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"La candidose donne des pertes blanches caillebottées (« lait caillé ») avec un prurit intense ; elle est favorisée par la grossesse. Elle se traite par antifongiques ; le métronidazole traite le Trichomonas et la Gardnerella.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Leucorrhées p. 178-180\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"quels sont les facteurs qui ne favorisent pas l'anémie ferriprive au cours de la grossesse :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"les infections urinaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"les grossesses mono-fœtales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"la multigestité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"les grossesses rapprochées\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"les vomissements\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. les grossesses mono-fœtales ; C. la multigestité\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"La question demande ce qui ne favorise pas l'anémie. Le cours cite comme facteurs favorisants : alimentation pauvre en fer, multiparité, grossesses rapprochées, grossesses multiples, infections (surtout urinaires), troubles digestifs (vomissements), parasitoses. Une grossesse mono-fœtale n'est pas un facteur.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Anémie et grossesse p. 10-11\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Laquelle ou lesquelles des assertions concernant la toxoplasmose au cours de la grossesse est ou sont juste(s) :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"la sage-femme doit évoquer le diagnostic positif de toxoplasmose si IGG est positif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"ce sont les gestantes ayant une sérologie positive qui font l'objet d'une surveillance particulière\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"elle peut se compliquer de lésions oculaires et cérébrales du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"la sage-femme doit initier le traitement avant le transfert de la gestante.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Les anticorps G apparaissent dès le début de l'infestation, disparaissent à 4 mois ½.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. elle peut se compliquer de lésions oculaires et cérébrales du fœtus ; D. la sage-femme doit initier le traitement avant le transfert de la gestante.\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"La toxoplasmose congénitale donne des lésions cérébrales (hydrocéphalie, calcifications) et oculaires (choriorétinite…). Devant une séroconversion, la sage-femme commence la spiramycine avant de transférer. IgG positives avec IgM négatives = immunité ancienne, pas une infection ; ce sont les gestantes séronégatives qu'on surveille chaque mois ; les IgG persistent toute la vie. Remarque : Dans le sujet, la 1re option n'a pas de lettre (c'est l'option A).\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Toxoplasmose et grossesse p. 22-26\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"les complications obstétricales du diabète mal équilibré sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"preclampsie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"malformations fœtales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"oligoamnios\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"infections urinaires\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"rupture prématurée des membranes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. preclampsie ; B. malformations fœtales ; D. infections urinaires\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Diabète mal équilibré : HTA et pré-éclampsie, infections urinaires et vaginales, hydramnios (et non oligoamnios), malformations fœtales, macrosomie, mort in utero.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Diabète et grossesse p. 43-44\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"au troisième trimestre de grossesse, l'échographie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"permet d'apprécier le comportement fœtal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"se réalise idéalement entre 32 et 34 semaines d'aménorrhées\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"permet d'apprécier l'état des annexes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"permet l'étude de la qualité de l'œuf\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"permet de préciser la présentation fœtale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. permet d'apprécier le comportement fœtal ; E. permet de préciser la présentation fœtale\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"L'échographie du 3e trimestre sert au pronostic de l'accouchement : elle apprécie la croissance et le comportement fœtal (vitalité, mouvements) et précise la présentation. L'étude de la qualité de l'œuf relève du 1er trimestre. Remarque : L'état des annexes (placenta, liquide amniotique) est aussi regardé au 3e trimestre ; la correction nationale de la Prépa DE (les J) ne retient que A et E.\\n\\nSource : Cours de soins obstétricaux L2 SF, CPN recentrée (3e échographie) ; Gynécologie-Obstétrique L3 SF (INFAS 2024-2025) p. 195 (hors cours pour le détail)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les conditions de réalisation de l'allo immunisation dans le système rhésus sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une mère ayant un Rhésus négatif et un père géniteur de la grossesse ayant un Rhésus négatif.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un fœtus ayant un rhésus négatif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une mère ayant un Rhésus négatif et un père géniteur de la grossesse ayant un Rhésus positif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un fœtus ayant un Rhésus positif\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le passage à travers le placenta des hématies fœtales dans le sang maternel et la formation des anticorps immuns par la mère.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Une mère ayant un Rhésus négatif et un père géniteur de la grossesse ayant un Rhésus positif ; D. Un fœtus ayant un Rhésus positif\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Conditions : mère Rh négatif, père géniteur Rh positif, fœtus Rh positif. Si les deux parents sont Rh négatif, ou si le fœtus est Rh négatif, il n'y a pas d'incompatibilité.\\n\\nSource : SONU L3 SF, Incompatibilité p. 42-43\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"concernant le traitement du paludisme au cours de la grossesse par la quinine :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"à partir du 2ème jour de quinine injectable, la posologie est de 2 perfusions de 12mg/kg de quinine base par perfusion\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"les combinaisons thérapeutiques quinine + artéméther ou artésunate sont conseillées\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La Posologie du 1er jour de Quinine injectable en perfusion est de 24mg/kg de quinine base par jour répartie dans 2 perfusions\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"il y a nécessité de faire au minimum 2 jours de perfusion de quinine injectable\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La QUININE par voie orale est recommandée dans le traitement du paludisme simple à la posologie de 25 mg/kg/jour répartie en deux prises pendant 5 à 7 jours consécutifs\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. à partir du 2ème jour de quinine injectable, la posologie est de 2 perfusions de 12mg/kg de quinine base par perfusion ; D. il y a nécessité de faire au minimum 2 jours de perfusion de quinine injectable\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Quinine injectable : 3 perfusions le 1er jour, puis 2 perfusions par jour à partir du 2e jour, avec relais oral dès que possible. La quinine orale du paludisme simple se donne à 25 mg/kg/jour en trois prises (et non deux). On n'associe pas quinine et dérivés de l'artémisinine. Remarque : Les doses de 12 mg/kg par perfusion (option A) ne sont pas lisibles dans le cours scanné ; le cours confirme 3 perfusions le 1er jour, ce qui exclut C.\\n\\nSource : Gynécologie-Obstétrique L3 SF (INFAS 2024-2025), Paludisme et grossesse p. 5-6\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez ce jour à la maternité de Koko, Mme XY, 30 ans G5P1 avec 1 enfant vivant bien portant, 3 antécédents d'avortements provoqués, un antécédent de myomectomie. Elle consulte ce jour pour une fièvre à 40° sur une grossesse de 32 semaines d'aménorrhée.\",\n       \"text\": \"citer 3 pathologies fréquentes que vous pouvez évoquer devant cette fièvre chez Mme XY\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fibrome utérin en nécrobiose\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hépatite virale B\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pyélonéphrite aiguë\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cystite aigue\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Paludisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Hépatite virale B ; C. Pyélonéphrite aiguë ; E. Paludisme\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Devant une fièvre élevée pendant la grossesse : d'abord le paludisme, puis la pyélonéphrite aiguë (infection urinaire haute, fébrile) et l'hépatite virale. La cystite (infection basse) ne donne habituellement pas de fièvre à 40 °C ; le fibrome a été enlevé (myomectomie).\\n\\nSource : SONU L3 SF, Fièvre pendant la grossesse p. 86-91 (diagnostic différentiel)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j3-sf3__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Vous recevez ce jour à la maternité de Koko, Mme XY, 30 ans G5P1 avec 1 enfant vivant bien portant, 3 antécédents d'avortements provoqués, un antécédent de myomectomie. Elle consulte ce jour pour une fièvre à 40° sur une grossesse de 32 semaines d'aménorrhée.\",\n       \"text\": \"quels sont les examens paracliniques de première intention que vous allez demander devant cette fièvre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Echographie obstétricale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dosage des transaminases\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Examen cytobactériologique des urines\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Goutte épaisse\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Hémogramme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Examen cytobactériologique des urines ; D. Goutte épaisse\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"En première intention : la goutte épaisse (ou TDR/frottis) pour le paludisme et l'ECBU avec antibiogramme pour l'infection urinaire. Les autres examens viennent selon l'orientation.\\n\\nSource : SONU L3 SF, Paludisme (examens paracliniques p. 87) et Infection urinaire (ECBU obligatoire p. 92)\",\n       \"sourceDoc\": \"Révision J1 à J4 SF/M — corrigé expliqué (J3 Gynéco-obstétrique SF3)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
